package com.skyrpg.pets.client.model;

import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeDeformation;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;

/**
 * The Mole pet's cubes and their UVs, and which parts each rarity shows. GENERATED by tools/art/generate_pets.py from the
 * same cube table the textures are painted from: edit the table there, never this file.
 */
final class MolePetLayout {
    /** Textures: textures/entity/pet/mole_&lt;rarity&gt;.png, and _glow.png for the rarities in {@link #GLOW_RARITIES}. */
    static final String NAME = "mole";
    /** Model pixels to player model pixels: how big the pet floats at the shoulder. */
    static final float SCALE = 0.76f;
    /** Whether some texels are see-through (drawn with the translucent entity render type). */
    static final boolean TRANSLUCENT = false;
    /** Bit r (0 = Common) set: that rarity has a glow layer, drawn fullbright. */
    static final int GLOW_RARITIES = 0b11111;
    /** Parts only some rarities show: RARITY_PARTS[i] is shown for rarity r when bit r of RARITY_MASKS[i] is set. */
    static final String[] RARITY_PARTS = {"pick", "goggles", "crown"};
    static final int[] RARITY_MASKS = {0b11110, 0b01000, 0b10000};

    private MolePetLayout() {
    }

    static LayerDefinition create() {
        MeshDefinition mesh = new MeshDefinition();
        PartDefinition root = mesh.getRoot();
        PartDefinition p_pet = root.addOrReplaceChild("pet",
        CubeListBuilder.create()
                , PartPose.offset(0f, 0f, 0f));
        PartDefinition p_body = p_pet.addOrReplaceChild("body",
        CubeListBuilder.create()
                .texOffs(0, 0).addBox(-3.5f, -2.5f, -3f, 7f, 6f, 7f)
                .texOffs(24, 28).addBox(-0.5f, 1.5f, 3.75f, 1f, 1f, 2f, new CubeDeformation(0f, 0f, -0.25f))
                .texOffs(16, 28).addBox(-3f, 3f, 1.25f, 2f, 1f, 2f, new CubeDeformation(0f, 0f, 0.25f))
                .mirror(true)
                .texOffs(16, 28).addBox(1f, 3f, 1.25f, 2f, 1f, 2f, new CubeDeformation(0f, 0f, 0.25f))
                , PartPose.offset(0f, 0f, 0f));
        PartDefinition p_head = p_body.addOrReplaceChild("head",
        CubeListBuilder.create()
                .texOffs(28, 0).addBox(-3f, -4f, -4.5f, 6f, 5f, 5f)
                .texOffs(0, 28).addBox(-1f, -1f, -6.5f, 2f, 2f, 2f)
                .texOffs(30, 28).addBox(-1f, -1.25f, -7.375f, 2f, 2f, 1f, new CubeDeformation(-0.25f, -0.25f, -0.125f))
                , PartPose.offset(0f, -1.5f, -3f));
        p_head.addOrReplaceChild("lids",
        CubeListBuilder.create()
                .texOffs(62, 28).addBox(-2f, -3f, -4.55f, 1f, 2f, 0f)
                .mirror(true)
                .texOffs(62, 28).addBox(1f, -3f, -4.55f, 1f, 2f, 0f)
                , PartPose.offset(0f, 0f, 0f));
        PartDefinition p_helmet = p_head.addOrReplaceChild("helmet",
        CubeListBuilder.create()
                .texOffs(30, 13).addBox(-3f, -2f, -3f, 6f, 2f, 6f, new CubeDeformation(0.25f, 0f, -0.25f))
                .texOffs(48, 21).addBox(-2f, -2.875f, -2f, 4f, 1f, 4f, new CubeDeformation(0.25f, -0.125f, -0.25f))
                .texOffs(0, 13).addBox(-4f, -0.5f, -3.625f, 8f, 1f, 7f, new CubeDeformation(-0.25f, -0.25f, -0.125f))
                .texOffs(36, 28).addBox(-1f, -2.25f, -3.625f, 2f, 2f, 1f, new CubeDeformation(0.25f, 0f, -0.125f))
                , PartPose.offset(0f, -4f, -2f));
        p_helmet.addOrReplaceChild("goggles",
        CubeListBuilder.create()
                .texOffs(0, 21).addBox(-3.5f, -0.625f, -3f, 7f, 1f, 6f, new CubeDeformation(0f, -0.125f, 0f))
                .texOffs(42, 28).addBox(-3.3f, -1.1f, -3.65f, 2f, 2f, 1f, new CubeDeformation(-0.2f, -0.25f, -0.25f))
                .mirror(true)
                .texOffs(42, 28).addBox(1.3f, -1.1f, -3.65f, 2f, 2f, 1f, new CubeDeformation(-0.2f, -0.25f, -0.25f))
                , PartPose.offset(0f, -1.25f, 0f));
        p_helmet.addOrReplaceChild("crown",
        CubeListBuilder.create()
                .texOffs(30, 21).addBox(-2.5f, -0.5f, -2f, 5f, 1f, 4f)
                .texOffs(58, 28).addBox(-0.5f, -1.625f, -2f, 1f, 1f, 1f, new CubeDeformation(0f, 0.125f, 0f))
                .texOffs(58, 28).addBox(-2.5f, -1.375f, -2f, 1f, 1f, 1f, new CubeDeformation(0f, -0.125f, 0f))
                .texOffs(58, 28).addBox(1.5f, -1.375f, -2f, 1f, 1f, 1f, new CubeDeformation(0f, -0.125f, 0f))
                .texOffs(58, 28).addBox(-2.5f, -1.375f, 1f, 1f, 1f, 1f, new CubeDeformation(0f, -0.125f, 0f))
                .texOffs(58, 28).addBox(1.5f, -1.375f, 1f, 1f, 1f, 1f, new CubeDeformation(0f, -0.125f, 0f))
                , PartPose.offset(0f, -3f, 0f));
        PartDefinition p_paw_r = p_body.addOrReplaceChild("paw_r",
        CubeListBuilder.create()
                .texOffs(8, 28).addBox(-2.75f, -1.5f, -0.5f, 3f, 3f, 1f)
                , PartPose.offsetAndRotation(-3.25f, 1f, -3f, 0f, 0.45f, -0.3f));
        p_paw_r.addOrReplaceChild("pick",
        CubeListBuilder.create()
                .texOffs(26, 21).addBox(-0.5f, -4.25f, -0.5f, 1f, 6f, 1f, new CubeDeformation(-0.25f, 0.25f, -0.25f))
                .texOffs(48, 28).addBox(-2.25f, -5.25f, -0.5f, 4f, 1f, 1f, new CubeDeformation(0.25f, 0f, -0.1f))
                , PartPose.offsetAndRotation(-1.25f, -0.5f, -0.6f, 0f, 0f, 0.35f));
        p_body.addOrReplaceChild("paw_l",
        CubeListBuilder.create()
                .mirror(true)
                .texOffs(8, 28).addBox(-0.25f, -1.5f, -0.5f, 3f, 3f, 1f)
                , PartPose.offsetAndRotation(3.25f, 1f, -3f, 0f, -0.45f, 0.3f));
        return LayerDefinition.create(mesh, 64, 64);
    }
}
